"""Register explicit Postgres casts from bigint/integer to uuid.

Legacy integer primary keys are mapped deterministically into the UUID space
(zero-padded hex, e.g. 42 -> 00000000-0000-0000-0000-00000000002a), which lets
``ALTER COLUMN ... TYPE uuid USING "col"::uuid`` convert primary key columns
and every referencing foreign key column in place while preserving referential
integrity. Mapped values can never collide with uuid4 values because the
version nibble is zero.

The casts are explicit-only and stay installed so migration replays on fresh
databases keep working.
"""

from django.db import migrations

CREATE_CAST_SQL = """
CREATE OR REPLACE FUNCTION clancal_bigint_to_uuid(value bigint) RETURNS uuid
AS $$ SELECT lpad(to_hex(value), 32, '0')::uuid $$
LANGUAGE SQL IMMUTABLE STRICT PARALLEL SAFE;

CREATE OR REPLACE FUNCTION clancal_int_to_uuid(value integer) RETURNS uuid
AS $$ SELECT lpad(to_hex(value), 32, '0')::uuid $$
LANGUAGE SQL IMMUTABLE STRICT PARALLEL SAFE;

DROP CAST IF EXISTS (bigint AS uuid);
CREATE CAST (bigint AS uuid) WITH FUNCTION clancal_bigint_to_uuid(bigint);

DROP CAST IF EXISTS (integer AS uuid);
CREATE CAST (integer AS uuid) WITH FUNCTION clancal_int_to_uuid(integer);
"""

DROP_CAST_SQL = """
DROP CAST IF EXISTS (integer AS uuid);
DROP CAST IF EXISTS (bigint AS uuid);
DROP FUNCTION IF EXISTS clancal_int_to_uuid(integer);
DROP FUNCTION IF EXISTS clancal_bigint_to_uuid(bigint);
"""


class Migration(migrations.Migration):
    initial = True

    dependencies = []

    operations = [
        migrations.RunSQL(CREATE_CAST_SQL, reverse_sql=DROP_CAST_SQL),
    ]

