CREATE OR REPLACE FUNCTION clancal_bigint_to_uuid(value bigint) RETURNS uuid
AS $$ SELECT lpad(to_hex(value), 32, '0')::uuid $$
LANGUAGE SQL IMMUTABLE STRICT PARALLEL SAFE;

CREATE OR REPLACE FUNCTION clancal_int_to_uuid(value integer) RETURNS uuid
AS $$ SELECT lpad(to_hex(value), 32, '0')::uuid $$
LANGUAGE SQL IMMUTABLE STRICT PARALLEL SAFE;

DROP CAST IF EXISTS (bigint AS uuid);
CREATE CAST (bigint AS uuid) WITH FUNCTION clancal_bigint_to_uuid(bigint);

DROP CAST IF EXISTS (integer AS uuid);
CREATE CAST (integer AS uuid) WITH FUNCTION clancal_int_to_uuid(integer);
"""

DROP_CAST_SQL = """
DROP CAST IF EXISTS (integer AS uuid);
DROP CAST IF EXISTS (bigint AS uuid);
DROP FUNCTION IF EXISTS clancal_int_to_uuid(integer);
DROP FUNCTION IF EXISTS clancal_bigint_to_uuid(bigint);
"""

EXISTING_CASTS_SQL = """
SELECT s.typname
FROM pg_cast c
JOIN pg_type s ON s.oid = c.castsource
JOIN pg_type t ON t.oid = c.casttarget
WHERE t.typname = 'uuid' AND s.typname IN ('int8', 'int4')
"""

CAN_CREATE_CAST_SQL = """
SELECT EXISTS (
    SELECT 1 FROM pg_roles WHERE rolname = current_user AND rolsuper
) OR EXISTS (
    SELECT 1 FROM pg_type
    WHERE typname IN ('int8', 'uuid') AND pg_has_role(typowner, 'USAGE')
)
"""


def _existing_casts(cursor):
    cursor.execute(EXISTING_CASTS_SQL)
    return {row[0] for row in cursor.fetchall()}


def create_casts(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        return
    with schema_editor.connection.cursor() as cursor:
        if _existing_casts(cursor) >= {"int8", "int4"}:
            return
        cursor.execute(CAN_CREATE_CAST_SQL)
        if not cursor.fetchone()[0]:
            raise RuntimeError(
                "The bigint/integer -> uuid casts are missing and the current "
                "database user cannot create casts on built-in types. Run the "
                "following SQL once as a superuser, then re-run migrate:\n"
                f"{BOOTSTRAP_SQL}"
            )
        cursor.execute(BOOTSTRAP_SQL)


